1	// gcec local check: extension/event-extractors/custom/ holds per-site sources and
2	// nothing else — one flat `<site>.js` per site, no subdirectories, no other file
3	// kinds, and never a pipeline file (the registry, the orchestrator, the shared
4	// helpers, or the one core generic extractor, which is a different kind of thing
5	// from a per-site source). The architecture rule this converts is in RULES.md's
6	// "Architecture rules of the road": custom/ is THE extensibility point, which is
7	// what keeps adding a host a single-file change.
8	//
9	// Why a check and not just prose: the load-order generator (dev/build/gen-load-order.js)
10	// reads custom/ with `readdirSync(...).filter(f => f.endsWith('.js'))` — one level,
11	// name-filtered. A nested directory or a non-.js file is therefore SILENTLY dropped
12	// from load-order.generated.json: no error anywhere, the code simply never loads and
13	// the site quietly stops extracting. That silence is exactly what a static scan is for.
14	//
15	// Local-pack check modules are dependency-free on purpose (see
16	// test-offline-list-sync.mjs's header): plain finding objects, no engine imports,
17	// so they also load under the repo's own `npm test` (pack.test.mjs).
18	const id = 'custom-sources-flat';
19	const severity = 'blocking';
20	const doc = '.claudinite/local/packs/gcec/RULES.md';
21	const why =
22	  'gen-load-order.js reads custom/ one level deep and keeps only *.js — anything else ' +
23	  'is silently omitted from the load order and never runs';
24	
25	const DIR = 'extension/event-extractors/custom/';
26	
27	// The pipeline itself: these live in event-extractors/, never in custom/.
28	const PIPELINE_FILES = ['registry.js', 'generic-extractor.js', 'assemble-events.js'];
29	
30	export default {
31	  id,
32	  severity,
33	  description: 'extension/event-extractors/custom/ holds only flat per-site <site>.js sources',
34	  doc,
35	  why,
36	
37	  run(ctx) {
38	    const findings = [];
39	    // ctx.files is the whole repo under the default `all` sweep; a --changed run
40	    // narrows it, which only ever under-reports.
41	    for (const file of ctx.files) {
42	      if (!file.startsWith(DIR)) continue;
43	      const rest = file.slice(DIR.length);
44	
45	      if (rest.includes('/')) {
46	        findings.push({
47	          rule: id, severity, file, line: null,
48	          what: `${file} sits in a subdirectory of custom/`,
49	          why,
50	          fix: 'flatten it to extension/event-extractors/custom/<site>.js, or move shared code to event-extractors/helpers/',
51	          doc,
52	        });
53	        continue;
54	      }
55	
56	      if (!rest.endsWith('.js')) {
57	        findings.push({
58	          rule: id, severity, file, line: null,
59	          what: `${file} is not a per-site source (custom/ holds only <site>.js files)`,
60	          why,
61	          fix: 'move it out of custom/ — that directory is the per-site extensibility point and nothing else',
62	          doc,
63	        });
64	        continue;
65	      }
66	
67	      if (PIPELINE_FILES.includes(rest)) {
68	        findings.push({
69	          rule: id, severity, file, line: null,
70	          what: `${file} is a pipeline file, not a per-site source`,
71	          why: 'the registry, the orchestrator and the core generic extractor are the pipeline itself — a different kind of thing from a per-site override',
72	          fix: `move ${rest} back to extension/event-extractors/`,
73	          doc,
74	        });
75	      }
76	    }
77	    return findings;
78	  },
79	};
